    ptr = 0
    T = int(input[ptr])
    ptr += 1
    for _ in range(T):
        N = int(input[ptr])
        ptr += 1
        goals = list(map(int, input[ptr:ptr+N]))
        ptr += N
        max_diff = 0
        found = False
        for i in range(N):
            for j in range(i+1, N):
                diff = goals[j] - goals[i]
                if diff > max_diff:
                    max_diff = diff
                    found = True
        if found and max_diff > 0:
            print(max_diff)
        else:
            print("UNFIT")

if __name__ == "__main__":
    main()
